+@page "/board"
+@using sv_2848a3a85c6e48d9a18678d68c63682e
+@rendermode InteractiveServer
+@inject ITaskService TaskService
+
+<PageTitle>Kanban Board</PageTitle>
+
+<h2 class="mb-3">Project Board</h2>
+
+@if (_loading)
+{
+    <div class="d-flex justify-content-center py-5">
+        <div class="spinner-border" role="status">
+            <span class="visually-hidden">Loading…</span>
+        </div>
+    </div>
+}
+else if (_error is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @_error
+        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
+    </div>
+}
+else
+{
+    <!-- Stats bar -->
+    <div class="row g-2 mb-3">
+        <div class="col">
+            <div class="stats-card p-2 text-center rounded border">
+                <div class="fw-bold">@_allTasks.Count</div>
+                <small class="text-muted">Total</small>
+            </div>
+        </div>
+        @foreach (var col in Columns)
+        {
+            <div class="col">
+                <div class="stats-card p-2 text-center rounded border">
+                    <div class="fw-bold">@TasksForColumn(col).Count</div>
+                    <small class="text-muted">@col</small>
+                </div>
+            </div>
+        }
+        <div class="col">
+            <div class="stats-card p-2 text-center rounded border text-danger">
+                <div class="fw-bold">@OverdueCount</div>
+                <small>Overdue</small>
+            </div>
+        </div>
+    </div>
+
+    <!-- Search bar -->
+    <div class="mb-3">
+        <input type="text"
+               class="form-control"
+               placeholder="Search tasks by title…"
+               @bind="_searchTerm"
+               @bind:event="oninput" />
+    </div>
+
+    <!-- Kanban columns -->
+    <div class="row g-3">
+        @for (var i = 0; i < Columns.Length; i++)
+        {
+            var colIndex = i;
+            var column = Columns[colIndex];
+            var tasks = FilteredTasksForColumn(column);
+
+            <div class="col-md-4">
+                <div class="kanban-column rounded border p-3">
+                    <h5 class="d-flex justify-content-between align-items-center mb-3">
+                        <span>@column</span>
+                        <span class="badge bg-secondary">@tasks.Count</span>
+                    </h5>
+
+                    @foreach (var task in tasks)
+                    {
+                        <div class="card mb-2 task-card">
+                            <div class="card-body p-2">
+                                <div class="fw-semibold mb-1">@task.Title</div>
+                                <div class="d-flex justify-content-between align-items-center mb-1">
+                                    <small class="text-muted">@task.Assignee</small>
+                                    <span class="badge @PriorityClass(task.Priority)">@task.Priority</span>
+                                </div>
+                                <div class="d-flex justify-content-between align-items-center">
+                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                    <span>
+                                        @if (colIndex > 0)
+                                        {
+                                            <button class="btn btn-sm btn-outline-secondary py-0 px-1"
+                                                    @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex - 1])"
+                                                    disabled="@_moving">
+                                                ◀ Move Left
+                                            </button>
+                                        }
+                                        @if (colIndex < Columns.Length - 1)
+                                        {
+                                            <button class="btn btn-sm btn-outline-secondary py-0 px-1 ms-1"
+                                                    @onclick="() => MoveTaskAsync(task.Id, Columns[colIndex + 1])"
+                                                    disabled="@_moving">
+                                                Move Right ▶
+                                            </button>
+                                        }
+                                    </span>
+                                </div>
+                            </div>
+                        </div>
+                    }
+
+                    @if (_addingColumn == column)
+                    {
+                        <div class="card border-primary mb-2">
+                            <div class="card-body p-2">
+                                <input type="text" class="form-control form-control-sm mb-1"
+                                       placeholder="Title" @bind="_newTitle" />
+                                <input type="text" class="form-control form-control-sm mb-1"
+                                       placeholder="Assignee" @bind="_newAssignee" />
+                                <select class="form-select form-select-sm mb-1" @bind="_newPriority">
+                                    <option value="High">High</option>
+                                    <option value="Medium">Medium</option>
+                                    <option value="Low">Low</option>
+                                </select>
+                                <input type="date" class="form-control form-control-sm mb-1"
+                                       @bind="_newDueDate" />
+                                <div class="d-flex gap-1">
+                                    <button class="btn btn-sm btn-primary flex-fill"
+                                            @onclick="SaveNewTaskAsync"
+                                            disabled="@_saving">
+                                        @(_saving ? "Saving…" : "Save")
+                                    </button>
+                                    <button class="btn btn-sm btn-outline-secondary flex-fill"
+                                            @onclick="CancelAdd">
+                                        Cancel
+                                    </button>
+                                </div>
+                            </div>
+                        </div>
+                    }
+
+                    <button class="btn btn-sm btn-outline-primary w-100"
+                            @onclick="() => StartAdd(column)"
+                            disabled="@(_addingColumn is not null)">
+                        + Add Task
+                    </button>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _allTasks = new();
+    private bool _loading = true;
+    private string? _error;
+    private string _searchTerm = string.Empty;
+    private bool _moving;
+
+    // Add-task form state
+    private string? _addingColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+    private bool _saving;
+
+    protected override async Task OnInitializedAsync() => await LoadTasksAsync();
+
+    private async Task LoadTasksAsync()
+    {
+        _loading = true;
+        _error = null;
+        try
+        {
+            _allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private List<TaskItem> TasksForColumn(string status) =>
+        _allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> FilteredTasksForColumn(string status) =>
+        _allTasks
+            .Where(t => t.Status == status &&
+                        (string.IsNullOrWhiteSpace(_searchTerm) ||
+                         t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+
+    private int OverdueCount =>
+        _allTasks.Count(t => t.DueDate.Date < DateTime.Today);
+
+    private static string PriorityClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        _moving = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                var old = _allTasks[idx];
+                _allTasks[idx] = old with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _moving = false;
+        }
+    }
+
+    private void StartAdd(string column)
+    {
+        _addingColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => _addingColumn = null;
+
+    private async Task SaveNewTaskAsync()
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle) || _addingColumn is null)
+            return;
+
+        _saving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(
+                _newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);
+            // CreateTaskAsync returns a task with default status; override to match column
+            _allTasks.Add(created with { Status = _addingColumn });
+            if (created.Status != _addingColumn)
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, _addingColumn);
+            }
+            _addingColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

